'use strict';
angular.module('excaliburDualList', []).directive('excaliburDualList', [
  function () {
    return {
      restrict: 'E',
      require: 'ngModel',
      scope: { options: '=' },
      link: function (e, t, l, i) {
        ((e.transfer = function (e, t, l) {
          if (l >= 0) (t.push(e[l]), e.splice(l, 1));
          else {
            for (var i = 0; i < e.length; i++) t.push(e[i]);
            e.length = 0;
          }
        }),
          i.$setViewValue(e.options.selectedItems),
          i.$render());
      },
      templateUrl: 'bower_components/excalibur-duallist/excalibur-duallist.html',
    };
  },
]);
